.theme-light {
  --color-dark-subtle: linear-gradient(to right, #532222, #020202);
  --color-dark: #000000;
  --color-light: #fff7f7;
  --color-white: #ffffff;
  --color-red: #ff7a85d2;
  --color-red-light: #ffa7a7;
  --color-shadow-dark: rgb(31, 53, 31);
  --color-shadow-text: rgb(0 0 0 / 65%);
  --color-accent-bg: #ffa7ad4f;
  --shadow-light: -5px -5px 9px rgb(66, 48, 48);
  --shadow-dark: 5px 5px 9px rgb(128, 97, 97);
  --shadow-bar: -5px -5px 9px rgb(77 45 45 / 45%), 5px 5px 9px rgb(39 39 39);
}

.theme-light .card {
  border-radius: 16px;
  padding: 10px;
  width: 320px;
  background: var(--color-dark);
  position: relative;
  transition-duration: 0.2s;
  user-select: none;
}

.card:before,
.card:after {
  content: "";
  position: absolute;
  left: 0px;
  top: 0px;
  border-radius: 16px;
  background: linear-gradient(
    45deg,
    #fa0a0a,
    #eb021d,
    #f17917,
    #e763dc,
    #b96565,
    #e0d18b,
    #df6a0b,
    #956df3,
    #b15a65,
    #f5d103
  );
  background-size: 400%;
  width: calc(100% + 0px);
  height: calc(100% + 0px);
  z-index: -1;
  animation: steam 40s linear infinite;
}

@keyframes steam {
  0% {
    background-position: 0 0;
  }

  50% {
    background-position: 400% 0;
  }

  100% {
    background-position: 0 0;
  }
}

.card:after {
  filter: blur(20px);
}

.theme-light .flex {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 18px;
}

.theme-light .bar-label {
  text-shadow: 1px 1px 3px var(--color-shadow-text);
  font-size: 12px;
}

.theme-light .flex .tag {
  fill: var(--color-white);
  display: flex;
  align-items: center;
  justify-content: center;
  height: 25px;
  width: 25px;
  box-shadow: 4px 4px 3px var(--color-shadow-dark);
}

.theme-light .bg-custom {
  background: var(--color-dark-subtle);
  padding: 18px;
  margin-bottom: 10px;
  border-radius: 10px;
  box-shadow:
    inset var(--shadow-light),
    inset var(--shadow-dark);
}

.theme-light .bg-custom-2 {
  font-weight: 600;
}

.theme-light .pr-day {
  position: absolute;
  top: -25px;
  font-size: 12px;
  font-weight: 700;
  color: var(--color-white);
}

.theme-light .text-red {
  color: var(--color-red-light);
}

.theme-light .text-light {
  color: var(--color-light);
}

.theme-light .text-green {
  color: var(--color-white);
}

.theme-light .card .heading {
  margin: 0;
  font-size: 16px;
  font-weight: 500;
  color: var(--color-light);
  text-shadow: 4px 4px 3px var(--color-shadow-dark);
}

.theme-light .amount {
  font-size: 32px;
  font-weight: bold;
  margin: 10px 0;
  line-height: 1.2;
  text-shadow: 4px 4px 3px var(--color-shadow-dark);
  display: inline-flex;
  align-items: center;
}

.theme-light .typing {
  overflow: hidden;
  white-space: nowrap;
  border-right: 3px solid var(--color-white);
  display: inline-block;
  animation:
    typing 8s steps(20) infinite,
    blink 1.2s step-end infinite;
}

@keyframes typing {
  0% {
    width: 0;
  }

  40% {
    width: 128px;
  }

  60% {
    width: 128px;
  }

  100% {
    width: 0;
  }
}

@keyframes blink {
  50% {
    border-color: transparent;
  }
}

.theme-light .amount .main-pr {
  font-size: 14px;
  color: var(--color-red-light);
  margin-left: 6px;
  font-weight: 500;
  background: var(--color-accent-bg);
  border-radius: 5px;
  padding: 2px 4px;
}

.theme-light .compare {
  font-size: 12px;
  text-shadow: 4px 4px 3px var(--color-shadow-dark);
  letter-spacing: 1px;
}

.theme-light .chart {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  width: 300px;
  height: 140px;
  padding: 10px;
  border-radius: 12px;
}

.theme-light .bar {
  width: 20px;
  font-size: 15px;
  background: var(--color-red);
  color: var(--color-dark);
  border-radius: 4px 4px 0 0;
  display: flex;
  justify-content: center;
  align-items: flex-end;
  position: relative;
  transform: scaleY(0);
  transform-origin: bottom;
  animation: rippleBounce 7.5s ease-in-out infinite;
  box-shadow: var(--shadow-bar);
}

@keyframes rippleBounce {
  0%,
  100% {
    transform: scaleY(0.6);
  }

  25% {
    transform: scaleY(1.1);
  }

  50% {
    transform: scaleY(0.8);
  }

  75% {
    transform: scaleY(1.2);
  }
}

.theme-light .bar:nth-child(1) {
  height: 30px;
  animation-delay: 0.2s;
  background: var(--color-white);
}

.theme-light .bar:nth-child(2) {
  height: 80px;
  animation-delay: 0.4s;
}

.theme-light .bar:nth-child(3) {
  height: 50px;
  animation-delay: 0.6s;
  background: var(--color-white);
}

.theme-light .bar:nth-child(4) {
  height: 85px;
  animation-delay: 0.8s;
}

.theme-light .bar:nth-child(5) {
  height: 70px;
  animation-delay: 1s;
  background: var(--color-white);
}

.theme-light .bar:nth-child(6) {
  height: 80px;
  animation-delay: 1.2s;
}

.theme-light .bar:nth-child(7) {
  height: 60px;
  animation-delay: 1.4s;
  background: var(--color-white);
}

.theme-light .card .more-button {
  font-size: 16px;
  padding: 12px;
  border-radius: 10px;
  color: var(--color-dark);
  border: 0;
  width: 100%;
  margin-top: 10px;
  outline: none;
  background-color: var(--color-white);
  box-shadow: var(--shadow-bar);
  transition: ease all 0.3s;
  cursor: pointer;
}

.theme-light .card .more-button:hover {
  transform: translateY(-3px);
}

.theme-light .card .more-button:active {
  transform: scale(0.9);
}

.theme-light .tags {
  display: flex;
  margin-bottom: 8px;
  justify-content: end;
  color: var(--color-light);
  font-size: 12px;
  font-weight: 500;
  gap: 4px;
  text-shadow: 2px 3px 3px var(--color-shadow-dark);
}

.theme-light .tags span {
  padding: 3px 10px;
  background-color: #4d2c2c73;
  border-radius: 3px;
}
